package com.spaceagent.platform.automation.application;
import com.spaceagent.platform.agent.api.AgentApplicationApi;import com.spaceagent.platform.agent.domain.AgentDefinitionStatus;import com.spaceagent.platform.automation.api.AutomationTriggerApplicationApi;import com.spaceagent.platform.automation.domain.*;import com.spaceagent.shared.exception.BusinessException;import com.spaceagent.shared.time.TimeProvider;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class AutomationTriggerApplicationService implements AutomationTriggerApplicationApi{private final AutomationTriggerRepository repository;private final AgentApplicationApi agents;private final TimeProvider time;public AutomationTriggerApplicationService(AutomationTriggerRepository repository,AgentApplicationApi agents,TimeProvider time){this.repository=repository;this.agents=agents;this.time=time;}public TriggerView create(CreateCommand c){agent(c.tenantId(),c.ownerUserId(),c.agentId());String id=stable(c.tenantId()+"\n"+c.ownerUserId()+"\n"+required(c.idempotencyKey()));var proposed=build(id,id,1,null,c.tenantId(),c.ownerUserId(),c.agentId(),c.description(),c.prompt(),c.source());var existing=repository.findTrigger(c.tenantId(),c.ownerUserId(),id).orElse(null);if(existing!=null){if(!existing.configSha256().equals(proposed.configSha256()))throw conflict("AUTOMATION_TRIGGER_IDEMPOTENCY_CONFLICT");return view(existing);}try{repository.insertTrigger(proposed);}catch(DataIntegrityViolationException|IllegalStateException race){var winner=repository.findTrigger(c.tenantId(),c.ownerUserId(),id).orElseThrow(()->race);if(!winner.configSha256().equals(proposed.configSha256()))throw conflict("AUTOMATION_TRIGGER_IDEMPOTENCY_CONFLICT");return view(winner);}return view(proposed);}public TriggerView createVersion(CreateVersionCommand c){var lineage=repository.findTriggerLineage(c.tenantId(),c.ownerUserId(),c.triggerLineageId());if(lineage.isEmpty())throw notFound();var current=lineage.getLast();if(current.version()!=c.expectedCurrentVersion())throw conflict("AUTOMATION_TRIGGER_VERSION_STALE");String id=stable(c.triggerLineageId()+"\n"+(current.version()+1)+"\n"+required(c.idempotencyKey()));var next=build(id,current.lineageId(),current.version()+1,current.id(),c.tenantId(),c.ownerUserId(),current.agentId(),c.description(),c.prompt(),c.source());repository.insertTrigger(next);return view(next);}public TriggerView activate(LifecycleCommand c){var current=require(c);if(current.state()==AutomationTriggerState.DRAFT&&repository.findSubscriptionByTrigger(current.id()).isEmpty()){Instant now=time.now();repository.insertSubscription(new AutomationTriggerPersistence.Subscription(stable("subscription\n"+current.id()),current.id(),current.lineageId(),current.tenantId(),current.ownerId(),current.type(),current.configSha256(),AutomationTriggerPersistence.SubscriptionState.ACTIVE,1,now,now,null));}return update(current,current.activate(time.now()),c.expectedRevision());}public TriggerView pause(LifecycleCommand c){var current=require(c);return update(current,current.pause(),c.expectedRevision());}public TriggerView archive(LifecycleCommand c){var current=require(c);return update(current,current.archive(time.now()),c.expectedRevision());}public TriggerView get(GetQuery q){return view(repository.findTrigger(q.tenantId(),q.ownerUserId(),q.triggerVersionId()).orElseThrow(this::notFound));}public List<TriggerView> list(ListQuery q){agent(q.tenantId(),q.ownerUserId(),q.agentId());return repository.findByAgent(q.tenantId(),q.ownerUserId(),q.agentId()).stream().map(this::view).toList();}private TriggerView update(AutomationTrigger old,AutomationTrigger next,long expected){if(old.revision()!=expected)throw conflict("AUTOMATION_TRIGGER_REVISION_CONFLICT");return view(repository.updateTrigger(next,expected).orElseThrow(()->conflict("AUTOMATION_TRIGGER_REVISION_CONFLICT")));}private AutomationTrigger require(LifecycleCommand c){return repository.findTrigger(c.tenantId(),c.ownerUserId(),c.triggerVersionId()).orElseThrow(this::notFound);}private void agent(String t,String o,String id){agents.findById(id).filter(v->v.tenantId().equals(t)&&v.ownerId().equals(o)&&v.status()==AgentDefinitionStatus.ACTIVE).orElseThrow(this::notFound);}private AutomationTrigger build(String id,String lineage,int version,String previous,String t,String o,String agent,String description,String prompt,AutomationTriggerSource source){String d=required(description),p=required(prompt);String hash=AutomationTrigger.calculateConfigSha256(t,o,agent,d,p,source.type(),source);return new AutomationTrigger(id,lineage,version,previous,t,o,agent,d,p,source.type(),source,hash,AutomationTriggerState.DRAFT,1,time.now(),null,null);}private TriggerView view(AutomationTrigger v){return new TriggerView(v.id(),v.lineageId(),v.version(),v.previousVersionId(),v.agentId(),v.description(),v.prompt(),v.type().name(),v.configSha256(),v.state().name(),v.revision(),v.createdAt(),v.activatedAt(),v.archivedAt());}private static String stable(String v){return UUID.nameUUIDFromBytes(v.getBytes(StandardCharsets.UTF_8)).toString();}private static String required(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("required value missing");return v.trim();}private BusinessException notFound(){return new BusinessException("Automation Trigger not found",HttpStatus.NOT_FOUND,"AUTOMATION_TRIGGER_NOT_FOUND");}private static BusinessException conflict(String c){return new BusinessException("Automation Trigger conflict",HttpStatus.CONFLICT,c);}}
